import{_ as a,o as t,c as i,ae as r}from"./chunks/framework.CK6jtcgr.js";const p=JSON.parse('{"title":"Auth Recovery and Connection Health","description":"","frontmatter":{},"headers":[],"relativePath":"guide/auth-recovery-and-connection-health.md","filePath":"guide/auth-recovery-and-connection-health.md"}'),o={name:"guide/auth-recovery-and-connection-health.md"};function l(s,e,n,c,h,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="auth-recovery-and-connection-health" tabindex="-1">Auth Recovery and Connection Health <a class="header-anchor" href="#auth-recovery-and-connection-health" aria-label="Permalink to &quot;Auth Recovery and Connection Health&quot;">​</a></h1><p>Real auth flows fail. The product must make those failures survivable.</p><h2 id="recovery-states" tabindex="-1">Recovery states <a class="header-anchor" href="#recovery-states" aria-label="Permalink to &quot;Recovery states&quot;">​</a></h2><p>SocioProphet treats auth and provider failures as explicit states rather than generic errors.</p><p>Common states include:</p><ul><li>callback capture failure</li><li>expired auth</li><li>insufficient scopes</li><li>limited capability</li><li>revoked token</li><li>unavailable browser session</li><li>local runtime not installed</li></ul><h2 id="recovery-patterns" tabindex="-1">Recovery patterns <a class="header-anchor" href="#recovery-patterns" aria-label="Permalink to &quot;Recovery patterns&quot;">​</a></h2><p>The recovery UX includes:</p><ul><li>re-auth</li><li>alternate auth method</li><li>paste callback URL</li><li>reconnect provider</li><li>manage scopes</li><li>install local runtime</li><li>review capability health</li></ul><h2 id="why-recovery-is-first-class" tabindex="-1">Why recovery is first-class <a class="header-anchor" href="#why-recovery-is-first-class" aria-label="Permalink to &quot;Why recovery is first-class&quot;">​</a></h2><p>Browser/OAuth and provider flows are messy in the real world. A platform that hides this mess without giving users recovery paths becomes brittle. SocioProphet instead turns auth failure into a managed workflow.</p><h2 id="public-website-role" tabindex="-1">Public website role <a class="header-anchor" href="#public-website-role" aria-label="Permalink to &quot;Public website role&quot;">​</a></h2><p>The public website surfaces this reality through <code>/auth/</code>, <code>/auth/sign-in/</code>, <code>/auth/connections/</code>, and <code>/auth/recovery/</code>.</p><p>The website is not merely describing a sign-in page. It is describing the product contract:</p><ul><li>one SocioProphet login</li><li>providers as capabilities</li><li>graceful recovery when auth gets weird</li></ul>',15)])])}const v=a(o,[["render",l]]);export{p as __pageData,v as default};
